/**
 * Extract requirement data published by the data overlay (`extractRequirements`, generated by
 * its `eft:extracts` from the game client's location and global definitions, and the curated
 * `extractCues`). Shapes mirror the overlay schemas; the server validates them before the
 * sections count as consumed, and the client checks them again before replacing its fallback.
 */
export type ExtractRuleType =
  'transfer' | 'coop' | 'activation' | 'empty' | 'train' | 'timer' | 'item' | 'chance' | 'unknown';
export type ExtractCueType = 'green_flare' | 'flare' | 'green_smoke' | 'key';
export type ExtractRule = {
  type: ExtractRuleType | ExtractCueType;
  item?: string;
  count?: number;
  countPve?: number;
  vehicle?: boolean;
  slot?: string;
  percent?: number;
  percentPve?: number;
  min?: number;
  max?: number;
  minPve?: number;
  maxPve?: number;
};
export type ExtractRuleEntry = {
  name: string;
  rules?: ExtractRule[];
  pvp?: ExtractRule[];
  seasonal?: ExtractRule[];
};
export type ExtractRuleSource = { clientBuild: string; definitionsSha256: string };
export type ExtractRequirementsSection = {
  sources: { regular: ExtractRuleSource; 'pvp-season'?: ExtractRuleSource };
  maps: Record<string, Record<string, ExtractRuleEntry>>;
};
export type ExtractCueEntry = { name: string; cues: ExtractRule[]; reference: string };
export type ExtractCuesSection = Record<string, Record<string, ExtractCueEntry>>;
export type ExtractRuleData = {
  requirements: ExtractRequirementsSection;
  cues: ExtractCuesSection;
};
type JsonRecord = Record<string, unknown>;
const isRecord = (value: unknown): value is JsonRecord =>
  value !== null && typeof value === 'object' && !Array.isArray(value);
const nonEmpty = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0;
const RULE_TYPES = new Set<string>([
  'transfer',
  'coop',
  'activation',
  'empty',
  'train',
  'timer',
  'item',
  'chance',
  'unknown',
]);
const CUE_TYPES = new Set<string>(['green_flare', 'flare', 'green_smoke', 'key']);
const NUMERIC_FIELDS = [
  'count',
  'countPve',
  'percent',
  'percentPve',
  'min',
  'max',
  'minPve',
  'maxPve',
] as const;
const optionalNumber = (value: unknown) =>
  value === undefined || (typeof value === 'number' && Number.isFinite(value) && value >= 0);
const optionalString = (value: unknown) => value === undefined || nonEmpty(value);
function validRule(value: unknown, types: Set<string>): boolean {
  if (!isRecord(value) || !types.has(value.type as string)) return false;
  return [
    NUMERIC_FIELDS.every((field) => optionalNumber(value[field])),
    optionalString(value.item) && optionalString(value.slot),
    value.vehicle === undefined || typeof value.vehicle === 'boolean',
  ].every(Boolean);
}
const validRuleList = (value: unknown, types: Set<string>) =>
  value === undefined || (Array.isArray(value) && value.every((rule) => validRule(rule, types)));
function validEntry(value: unknown): boolean {
  if (!isRecord(value) || !nonEmpty(value.name)) return false;
  const lists = [value.rules, value.pvp, value.seasonal];
  return lists.some(Array.isArray) && lists.every((list) => validRuleList(list, RULE_TYPES));
}
const validCueEntry = (value: unknown): boolean =>
  isRecord(value) &&
  nonEmpty(value.name) &&
  nonEmpty(value.reference) &&
  Array.isArray(value.cues) &&
  value.cues.length > 0 &&
  validRuleList(value.cues, CUE_TYPES);
/** Map ID -> extract ID -> entry, with every entry valid. */
const validNestedRecords = (value: unknown, entry: (value: unknown) => boolean): boolean =>
  isRecord(value) &&
  Object.values(value).every((map) => isRecord(map) && Object.values(map).every(entry));
const validSource = (value: unknown): boolean =>
  isRecord(value) && nonEmpty(value.clientBuild) && nonEmpty(value.definitionsSha256);
function validSources(value: unknown): boolean {
  if (!isRecord(value) || !validSource(value.regular)) return false;
  return value['pvp-season'] === undefined || validSource(value['pvp-season']);
}
export const isExtractRequirementsSection = (value: unknown): value is ExtractRequirementsSection =>
  isRecord(value) && validSources(value.sources) && validNestedRecords(value.maps, validEntry);
export const isExtractCuesSection = (value: unknown): value is ExtractCuesSection =>
  validNestedRecords(value, validCueEntry);
export const isExtractRuleData = (value: unknown): value is ExtractRuleData =>
  isRecord(value) &&
  isExtractRequirementsSection(value.requirements) &&
  isExtractCuesSection(value.cues);
